def MSR(*a, **k):
 for Z in range(3):
  try:return bitgn.llm(*a, **k)
  except Exception as X:
   U=str(X).upper()
   m=re.search('HTTP (\d{3})',U)
   if m and m.group(1)[0]!='5':raise
   if not m and not any(W in U for W in ('TIMED OUT','TIMEOUT','CONNECTION','UNAVAILABLE')):raise
   if Z==2:raise

